// 1. Normalizar ítems del Webhook: Convertir múltiples propiedades binarias (file_0, file_1...) en ítems individuales
const results = [];
const webhookData = $input.first().json;
const body = webhookData.body || {};
const query = webhookData.query || {};

// Extraer metadatos de seguridad y negocio
const institucionId = body.institucion_id || query.institucion_id;
const cursoId = body.curso_id || query.curso_id;
const coordinadorId = body.coordinador_id || query.coordinador_id || 'no_especificado';

if (!institucionId || !cursoId) {
  throw new Error('Error de Seguridad [400]: Los parámetros institucion_id y curso_id son obligatorios para el aislamiento de datos.');
}

// Iterar sobre todos los binarios recibidos y convertirlos en ítems uniformes con clave 'data'
const binaryData = $input.first().binary || {};
for (const [key, fileObj] of Object.entries(binaryData)) {
  results.push({
    json: {
      institucion_id: String(institucionId),
      curso_id: String(cursoId),
      coordinador_id: String(coordinadorId),
      originalKey: key,
      fileName: fileObj.fileName || `documento_${key}.pdf`
    },
    binary: {
      data: fileObj
    }
  });
}

if (results.length === 0) {
  throw new Error('Error [400]: No se detectaron archivos binarios en la petición.');
}

return results;

// Enriquecimiento de Metadatos por Archivo para LangChain y Vectorización
const results = [];
const timestamp = new Date().toISOString();
const archivosConError = [];

for (const item of $input.all()) {
  const textContent = item.json.data || item.json.text || '';
  const fileName = $('Normalizar Múltiples Binarios').first().json.fileName ;
  const institucionId = $('Normalizar Múltiples Binarios').first().json.institucion_id ;
  const cursoId = $('Normalizar Múltiples Binarios').first().json.curso_id ;
  const coordinadorId = $('Normalizar Múltiples Binarios').first().json.coordinador_id ;

  // Detección granular: Si un archivo es escaneado o sin texto, se reporta sin tumbar los demás
  if (!textContent.trim()) {
    archivosConError.push(fileName);
    continue;
  }

  const namespace = `inst_${institucionId}_curso_${cursoId}`;

  results.push({
    json: {
      pageContent: textContent,
      metadata: {
        sourceFile: fileName,
        namespace: namespace,
        institucion_id: institucionId,
        curso_id: cursoId,
        coordinador_id: coordinadorId,
        uploadedAt: timestamp
      },
      // Pasamos el binario intacto para el respaldo en Drive en el siguiente paso
      hasError: false
    },
    binary: item.binary
  });
}

if (results.length === 0) {
  throw new Error(`[Error 422 de Lectura]: Ninguno de los PDFs subidos contenía texto legible. Archivos con fallo de lectura/OCR: [${archivosConError.join(', ')}]`);
}

return results;

// Tomamos los metadatos del primer archivo del lote (todos pertenecen a la misma institución en esta petición)
const folderName = 'INST_' + $('Normalizar Múltiples Binarios').first().json.institucion_id;

return [{
  json: {
    folderName: folderName,
    institucion_id: $('Normalizar Múltiples Binarios').first().json.institucion_id,
    curso_id: $('Normalizar Múltiples Binarios').first().json.curso_id,
    coordinador_id: $('Normalizar Múltiples Binarios').first().json.coordinador_id
  }
}];

// 1. Atrapamos los datos de la carpeta que acaba de salir de la rama ganadora
// No importa si viene de "Buscar Carpeta" o "Crear Carpeta", $input.all() toma el nodo activo.
const folderInput = $input.all();

if (!folderInput || folderInput.length === 0 || !folderInput[0].json.id) {
  throw new Error("Error Crítico: No se recibió un ID de carpeta válido desde el paso anterior en Google Drive.");
}

const targetFolderId = folderInput[0].json.id;
const folderName = folderInput[0].json.name;

// 2. Traer los archivos binarios intactos desde el nodo origen de PDFs
const pdfItems = $('Normalizar Múltiples Binarios').all();

// 3. Empaquetamos cada PDF inyectándole el ID exacto y nombre de la carpeta destino
const results = [];

for (const item of pdfItems) {
  results.push({
    json: {
      ...item.json,
      targetFolderId: targetFolderId,
      targetFolderName: folderName,
      // Nos aseguramos de que haya un nombre de archivo válido para Drive
      fileName: item.json.fileName || item.json.name || 'documento.pdf'
    },
    binary: item.binary // Pasamos el binario intacto
  });
}

return results;

// 1. Tomamos los resultados que acaban de salir del nodo de Google Drive
const driveResults = $input.all();
if (driveResults.length === 0) {
  throw new Error("No se recibieron archivos desde el nodo anterior de Google Drive.");
}

// 2. Extraemos los datos directamente de las propiedades heredadas en el primer ítem del input
// (Así evitamos el error de 'hasn't been executed' al no depender de búsquedas hacia atrás)
const firstItemJson = driveResults[0].json;
const institucionId = firstItemJson.institucion_id || 'no_especificado';
const cursoId = firstItemJson.curso_id || 'no_especificado';
const coordinadorId = firstItemJson.coordinador_id || 'no_especificado';
const targetFolderName = firstItemJson.targetFolderName || `INST_${institucionId}`;
const targetFolderId = firstItemJson.targetFolderId || '';

// 3. Obtenemos metadatos secundarios de forma segura (con fallback si no se ejecutaron en la misma sesión)
let namespace = `inst_${institucionId}_curso_${cursoId}`;
let totalChunks = 0;

try {
  const metaNode = $('Enriquecer Metadatos y Aislamiento').first();
  if (metaNode && metaNode.json && metaNode.json.metadata) {
    namespace = metaNode.json.metadata.namespace;
  }
} catch (e) {
  // Usará el namespace por defecto generado arriba
}

try {
  const pineconeResults = $('Pinecone: Insertar Vectores Aislados').all();
  totalChunks = pineconeResults ? pineconeResults.length : 0;
} catch (e) {
  // Si se ejecuta de forma aislada sin memoria de Pinecone, pondrá 0
}

// 4. Mapeamos los archivos guardados en Google Drive
const archivosRespaldados = driveResults.map(item => ({
  fileId: item.json.id,
  fileName: item.json.name || item.json.fileName,
  webViewLink: item.json.webViewLink || ''
}));

// 5. Retornamos la estructura limpia para el Webhook
return [{
  json: {
    success: true,
    status: 200,
    message: `Materiales vectorizados y respaldados correctamente en la carpeta '${targetFolderName}'.`,
    data: {
      institucion_id: institucionId,
      curso_id: cursoId,
      coordinador_id: coordinadorId,
      pinecone: {
        namespace: namespace,
        index: "blindev-web",
        total_pdfs_vectorizados: driveResults.length,
        total_chunks_generados: totalChunks
      },
      googleDriveBackup: {
        folderName: targetFolderName,
        folderId: targetFolderId,
        total_archivos_guardados: archivosRespaldados.length,
        archivos: archivosRespaldados
      }
    }
  }
}];
